import numpy as np


def make_grid(n, n_cols):
    return np.arange(1, n + 1).reshape(-1, n_cols)


def describe(a):
    a = np.asarray(a)
    return {
        "shape": a.shape,
        "ndim": a.ndim,
        "size": a.size,
        "col_sums": a.sum(axis=0),
        "row_sums": a.sum(axis=1),
        "total": a.sum(),
    }


grid = make_grid(12, 4)
print(grid)
print(describe(grid))

